using UnityEngine;
using UnityEngine.Events;

namespace Gamekit2D
{
    // Generated by AI
    [RequireComponent(typeof(Collider2D))]
    public sealed class ForestCleanupCollectible : MonoBehaviour
    {
        [SerializeField] private ForestCareProgress progress;
        [SerializeField] private AudioClip cleanupSound;
        [SerializeField] private UnityEvent onCollected = new UnityEvent();

        private bool hasBeenCollected;

        public void Initialize(ForestCareProgress sceneProgress)
        {
            progress = sceneProgress;
            Collider2D triggerCollider = GetComponent<Collider2D>();
            if (triggerCollider != null)
                triggerCollider.isTrigger = true;
        }

        private void OnTriggerEnter2D(Collider2D other)
        {
            if (hasBeenCollected || other.GetComponentInParent<PlayerCharacter>() == null)
                return;

            if (progress == null)
                progress = FindObjectOfType<ForestCareProgress>();

            if (progress == null)
            {
                Debug.LogError("ForestCareProgress is missing from the scene.", this);
                return;
            }

            if (!progress.TryRegisterCleanup())
                return;

            hasBeenCollected = true;
            onCollected.Invoke();

            if (cleanupSound != null)
                AudioSource.PlayClipAtPoint(cleanupSound, transform.position);

            Destroy(gameObject);
        }

        private void OnValidate()
        {
            Collider2D triggerCollider = GetComponent<Collider2D>();
            if (triggerCollider != null && !triggerCollider.isTrigger)
                Debug.LogWarning("Set this collectible's Collider2D to Is Trigger.", this);
        }
    }
}
